"""Versioned experimental allowances, NOT a second allocation/fit model.

The native inventory predicts input-dependent allocations and owns admission.
These raw additional allowances reproduce one bounded successful configuration;
they are conservative policy, not calibrated peaks or arbitrary-scene bounds.
"""

VERSION = 'experimental-stereo-v1'
# Generated by the canonical allocation-closure generator for the supported
# native implementation. Changes require a policy compatibility review, not a
# new observation interpreted as automatic qualification.
ALLOCATION_FINGERPRINT = '1e2a25161b0b8cfea29c6c7c08699f65c835e37141645cd545afe3ed8dd19102'
DEFAULTS = {
    'loader_scratch_host_bytes': 512 * 1024**2,
    'process_host_bytes': 512 * 1024**2,
    'process_device_bytes': 512 * 1024**2,
    'unknown_host_bytes': 1024**3,
    'unknown_device_bytes': 1024**3,
    'reserve_host_bytes': 512 * 1024**2,
    'reserve_device_bytes': 512 * 1024**2,
}
BASIS = ('Conservative policy allowances from one bounded nine-photo execution '
         'with explicit 12 GiB caps and 1600-pixel dense resize; '
         'not measured overhead, calibration, or a physical-fit guarantee. '
         'Process/unknown are additional future allowances, not live usage.')


def validate_overrides(args):
    """Keep explicit unknown allowances attributable, including partial overrides."""
    explicit_unknown = any(getattr(args, name) is not None for name in
                           ('unknown_host_bytes', 'unknown_device_bytes'))
    if explicit_unknown and not (args.unknown_provenance or '').strip():
        raise ValueError('explicit unknown overrides require --unknown-provenance')
    host = args.unknown_host_bytes
    device = args.unknown_device_bytes
    if host == 0 and device == 0:
        raise ValueError('positive unknown allowance required on at least one side')
    if args.unknown_provenance is not None and not args.unknown_provenance.strip():
        raise ValueError('--unknown-provenance must not be blank')


def select_policy(args, identity):
    """Fill only absent terms; explicit expert declarations remain supported."""
    validate_overrides(args)
    defaults_needed = any(getattr(args, name) is None for name in DEFAULTS)
    fingerprint = identity['allocation_fingerprint']
    if defaults_needed and fingerprint != ALLOCATION_FINGERPRINT:
        raise ValueError('automatic resource policy has no supported allocation binding for '
                         + fingerprint + '; install a supported native build or provide all '
                         'expert byte allowances and --unknown-provenance')
    terms = {}
    for name, default in DEFAULTS.items():
        value = getattr(args, name)
        supplied = value is not None
        if not supplied:
            value = default
        terms[name] = dict(bytes=value, origin='user' if supplied else 'default',
                           classification='expert-override' if supplied else 'conservative-policy',
                           provenance=(args.unknown_provenance if supplied and name.startswith('unknown_')
                                       else 'explicit expert override' if supplied else BASIS))
        setattr(args, name, value)
    # Native protocol has a single provenance string for the unknown pair.
    args.unknown_provenance = '; '.join(
        name + ': ' + terms[name]['provenance']
        for name in ('unknown_host_bytes', 'unknown_device_bytes'))
    return dict(version=VERSION, allocation_fingerprint=fingerprint,
                selection='defaults-and-overrides' if defaults_needed else 'expert',
                scope='experimental logical feature extraction, exhaustive SIFT matching, initial CPU mapping payload/graph growth, stereo, undistortion and mapped CPU fusion admission', terms=terms,
                extraction=dict(input_payload='native same-decoder uint8 header, conversion/thumbnail/gravity-rotation overlap; credits through writer',
                                output_payload='native SIFT runtime requested/actual capacities and owned scratch; conservative credits through writer retirement',
                                supported='grayscale SIFT CPU/covariant/GPU; no masks; native host observation required',
                                policy='loader_scratch_host + process_host + unknown_host (raw, once)',
                                unknown='VLFeat/SiftGPU host/device workspace, OIIO, SQLite caches, metadata, allocator; full physical fit UNKNOWN'),
                matching=dict(input_payload='native actual SQLite feature shapes/dtype and stored match rows; conservative whole-DB plus detached-cache/index overlap',
                              lifetime='cache/index and CUDA buffers through actual worker/cache destruction; pair credits through DB writer payload retirement',
                              supported='exhaustive non-guided/non-rig SIFT; default CPU FAISS or native CUDA GPU; no multiple models or descriptor truncation',
                              host_policy='loader_scratch_host + process_host + unknown_host (raw, once)',
                              device_policy='process_device + unknown_device (raw, once; selected CUDA backend only)',
                              unknown='FAISS training/search/list capacity, estimator/RANSAC/solver scratch, SQLite, metadata, driver and allocator; whole-DB can over-refuse; full physical fit UNKNOWN'),
                mapping=dict(input_payload='native SQLite metadata snapshot before keypoint/two-view payloads; all-DB conservative overlap',
                             growth='actual correspondence vector old/new and flattening overlap; initial model Point2D copies and observation counters/pyramids',
                             lifetime='shared graph counted once; retained model-copy credits live until owner destruction, conservatively not credited at TearDown',
                             supported='fresh incremental CPU Ceres; ba_gpu_index alone does not enable GPU; legacy zero unchanged',
                             policy='loader_scratch_host + process_host + unknown_host (raw, once); no device policy on CPU mapping',
                             unknown='point3D/track growth, triangulation and other model copies, RANSAC/Ceres/solver workspace, full-resolution color decoding, metadata/hash/SQLite/allocator; NOT a whole-SfM hard cap or physical-fit guarantee'),
                undistortion=dict(basis='Reuses uncalibrated phase host allowances; no undistortion physical-fit calibration',
                                  input_payload='native actual-header/model RGB bitmap lifetime peak; ordered memory-admitted workers',
                                  supported='COLMAP; uint8 1-4 channels; perspective or spherical; no ROI',
                                  policy='loader_scratch_host + process_host + unknown_host (raw, once)',
                                  unknown='decoder/OIIO filters/writer scratch/model metadata/allocator; full physical fit UNKNOWN'),
                fusion=dict(input_payload='native ordered RGB/mask peak; mapped payload separate',
                            output_payload='native runtime vector capacities including merge overlap',
                            policy='loader_scratch_host + process_host + unknown_host (raw, once)',
                            unknown='decoder/scratch/metadata/allocator/traversal; not physical fit'),
                predicted_allocations='canonical native input-dependent inventory',
                measured_capacity='native FREE host/cgroup and selected CUDA device; caps only lower',
                margin='one aggregate 3% applied by native admission; no Python margin',
                live_usage='already excluded from FREE; never subtract again',
                whole_pipeline_physical_fit=None,
                unknown_physical_stages=['feature_extraction', 'matching', 'mapping', 'stereo', 'undistortion', 'fusion'])
